(function(){
'use strict';
if(window.__SP_L8T3_SENTENCE_ANALYSIS_UI_20260902_V2)return;
window.__SP_L8T3_SENTENCE_ANALYSIS_UI_20260902_V2=true;

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot',"'":'&#39;'}[c]));
const shuffle=a=>{const x=[...a];for(let i=x.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[x[i],x[j]]=[x[j],x[i]]}return x};
let feedback='';
function themeNo(){return Number(window.L8_THEME?.number||document.body?.dataset?.theme||3)}
function taskNo(task){const i=(window.L8_THEME?.tasks||[]).findIndex(t=>t?.id===task?.id);return i>=0?i+1:''}
function load(task){return window.L8S.load(themeNo(),task.id,task.items.length)}
function save(task,state,sync=false){return window.L8S.save(themeNo(),task.id,state,sync)}
function current(task){const i=window.L8S.nextIndex(themeNo(),task.id,task.items.length);return Number.isInteger(i)?i:null}
function answerKey(name,index){return `${name}:${index}`}
function ensurePool(task,state,index,item){state.answers=state.answers||{};const key=answerKey('pool',index);if(!Array.isArray(state.answers[key])||state.answers[key].length!==item.tokens.length){let ids=shuffle(item.tokens.map((_,i)=>i));if(ids.every((v,i)=>v===i)&&ids.length>1)[ids[0],ids[1]]=[ids[1],ids[0]];state.answers[key]=ids;save(task,state,false)}return state.answers[key]}
function builtIds(state,index){return Array.isArray(state.answers?.[answerKey('built',index)])?state.answers[answerKey('built',index)]:[]}
function setBuilt(task,state,index,ids){state.answers=state.answers||{};state.answers[answerKey('built',index)]=ids;save(task,state,false)}
function doneRoles(state,index){return Array.isArray(state.answers?.[answerKey('roles',index)])?state.answers[answerKey('roles',index)]:[]}
function selectedIds(state,index,role){const key=answerKey(`selected-${role}`,index);return Array.isArray(state.answers?.[key])?state.answers[key]:[]}
function setSelected(task,state,index,role,ids){state.answers=state.answers||{};state.answers[answerKey(`selected-${role}`,index)]=ids;save(task,state,false)}
function activeRole(state,index){const done=doneRoles(state,index);if(!done.includes('sub'))return'sub';if(!done.includes('verb'))return'verb';return null}
function targetIndexes(item,role){return (item.segments||[]).map((s,i)=>s.role===role?i:-1).filter(i=>i>=0)}
function clearStage(state,index){state.answers=state.answers||{};['pool','built','orderOk','roles','selected-sub','selected-verb'].forEach(k=>delete state.answers[answerKey(k,index)])}
function progress(task,state){const p=Math.round(state.done.length/Math.max(1,task.items.length)*100);return `<div class="sp-sa-progress"><span>${state.done.length} von ${task.items.length} fertig</span><strong>${p}%</strong></div><div class="sp-sa-bar"><span style="width:${p}%"></span></div>`}
function stateHint(state,index){const tries=Number(state.tries?.[index]||0);if(tries===1)return'<div class="sp-sa-note bad">Noch nicht richtig.</div>';if(tries===2)return'<div class="sp-sa-note hint">Achte auf die Satzstellung und markiere danach direkt im Satz.</div>';if(tries>=3)return'<div class="sp-sa-note hint">Im Präteritum kommen hier nur Formen von <strong>sein</strong> und <strong>haben</strong> vor.</div>';return''}
function finish(){document.getElementById('app').innerHTML='<div class="l8-wrap"><section class="l8-card sp-sa-finish"><div>🏁</div><h2>Aufgabe abgeschlossen</h2><p>Du hast 15 Sätze gebaut und untersucht.</p><a class="l8-btn primary" href="index.html">Zur Übersicht</a></section></div>'}
function renderBuild(task,index,item,state){const pool=ensurePool(task,state,index,item),chosen=builtIds(state,index),remaining=pool.filter(id=>!chosen.includes(id));return `<section class="l8-card sp-sa-card"><div class="sp-sa-step">1 · Satz bauen</div><div class="sp-sa-built ${chosen.length?'':'empty'}">${chosen.length?chosen.map((id,pos)=>`<button type="button" data-remove="${pos}">${esc(item.tokens[id])}</button>`).join(' '):'Baue hier den Satz.'}</div><div class="sp-sa-pool">${remaining.map(id=>`<button type="button" data-token="${id}">${esc(item.tokens[id])}</button>`).join('')}</div><div class="sp-sa-actions"><button class="l8-btn secondary" id="spSaClear" type="button">Löschen</button><button class="l8-btn primary" id="spSaCheckOrder" type="button" ${chosen.length!==item.tokens.length?'disabled':''}>Prüfen</button></div>${feedback||stateHint(state,index)}</section>`}
function pieceClass(state,index,segIndex){if(selectedIds(state,index,'sub').includes(segIndex))return' role-sub';if(selectedIds(state,index,'verb').includes(segIndex))return' role-verb';return''}
function analysisSentence(item,state,index){const active=activeRole(state,index);return `<div class="sp-sa-sentence-flow">${item.segments.map((seg,i)=>`<button type="button" class="sp-sa-piece${pieceClass(state,index,i)}" data-piece="${i}" ${active?'':'disabled'}>${esc(seg.text)}</button>`).join(' ')}<span>.</span></div>`}
function roleQuestions(state,index){const done=doneRoles(state,index),active=activeRole(state,index);return `<div class="sp-sa-role-questions"><div class="sp-sa-role-question ${done.includes('sub')?'done':active==='sub'?'active':''}"><b>1. Wo ist das Subjekt?</b>${done.includes('sub')?' ✓':''}</div><div class="sp-sa-role-question ${done.includes('verb')?'done':active==='verb'?'active':''}"><b>2. Wo ist das Verb?</b>${done.includes('verb')?' ✓':''}</div><div class="sp-sa-role-question ${!active?'active':''}"><b>3. Welche Zeitform hat das Verb?</b></div></div>`}
function tensePanel(item,state,index){if(activeRole(state,index))return'';return `<div class="sp-sa-tense"><div class="sp-sa-choices">${['Präsens','Perfekt','Präteritum'].map(v=>`<button type="button" data-tense="${v}">${v}</button>`).join('')}</div></div>`}
function renderAnalysis(task,index,item,state){return `<section class="l8-card sp-sa-card"><div class="sp-sa-step">2 · Satz untersuchen</div>${analysisSentence(item,state,index)}${roleQuestions(state,index)}${tensePanel(item,state,index)}<div class="sp-sa-feedback">${feedback||stateHint(state,index)}</div></section>`}
function render(task){
 const root=document.getElementById('app'),S=window.L8S;if(!root||!S)return false;let state=load(task);if(state.done.length>=task.items.length){finish();return true}const index=current(task);if(index==null){finish();return true}state=load(task);const item=task.items[index],analysis=state.answers?.[answerKey('orderOk',index)]===true;
 root.innerHTML=`<div class="l8-wrap"><section class="l8-card sp-sa-head"><div class="sp-sa-kicker">Aufgabe ${taskNo(task)} · Satz ${index+1} von ${task.items.length}</div><h1>🧱 ${esc(task.title)}</h1><p>${esc(task.instruction)}</p>${progress(task,state)}</section>${analysis?renderAnalysis(task,index,item,state):renderBuild(task,index,item,state)}</div>`;
 feedback='';
 if(!analysis){
  document.querySelectorAll('[data-token]').forEach(btn=>btn.addEventListener('click',()=>{const x=load(task),ids=builtIds(x,index);ids.push(Number(btn.dataset.token));setBuilt(task,x,index,ids);render(task)}));
  document.querySelectorAll('[data-remove]').forEach(btn=>btn.addEventListener('click',()=>{const x=load(task),ids=builtIds(x,index);ids.splice(Number(btn.dataset.remove),1);setBuilt(task,x,index,ids);render(task)}));
  document.getElementById('spSaClear')?.addEventListener('click',()=>{const x=load(task);setBuilt(task,x,index,[]);render(task)});
  document.getElementById('spSaCheckOrder')?.addEventListener('click',()=>{let x=load(task);const text=builtIds(x,index).map(id=>item.tokens[id]).join(' '),target=item.sentence.replace(/[.!?]$/,'');if(S.equal(text,target)){x.answers=x.answers||{};x.answers[answerKey('orderOk',index)]=true;feedback='<div class="sp-sa-note ok">Richtig. Markiere jetzt das Subjekt.</div>';save(task,x,false);render(task)}else{S.wrong(themeNo(),task.id,task.items.length,index,text);x=load(task);setBuilt(task,x,index,[]);feedback='<div class="sp-sa-note bad">Der Satz ist noch nicht richtig.</div>';render(task)}})
 }else{
  document.querySelectorAll('[data-piece]').forEach(btn=>btn.addEventListener('click',()=>{
   let x=load(task);const role=activeRole(x,index);if(!role)return;const piece=Number(btn.dataset.piece),targets=targetIndexes(item,role),seg=item.segments[piece];if(seg?.role!==role){S.wrong(themeNo(),task.id,task.items.length,index,item.sentence);feedback=`<div class="sp-sa-note bad">Dieser Satzteil ist nicht das ${role==='sub'?'Subjekt':'Verb'}.</div>`;render(task);return}
   const ids=selectedIds(x,index,role);if(!ids.includes(piece))ids.push(piece);setSelected(task,x,index,role,ids);x=load(task);const complete=targets.every(id=>selectedIds(x,index,role).includes(id));if(!complete){feedback='<div class="sp-sa-note hint">Ein Verbteil ist markiert. Markiere auch den zweiten Verbteil.</div>';render(task);return}
   x.answers=x.answers||{};const roles=doneRoles(x,index);if(!roles.includes(role))roles.push(role);x.answers[answerKey('roles',index)]=roles;save(task,x,false);feedback=role==='sub'?'<div class="sp-sa-note ok">Richtig. Markiere jetzt das Verb.</div>':'<div class="sp-sa-note ok">Richtig. Wähle jetzt die Zeitform.</div>';render(task)
  }));
  document.querySelectorAll('[data-tense]').forEach(btn=>btn.addEventListener('click',()=>{const value=btn.dataset.tense;if(value!==item.tense){S.wrong(themeNo(),task.id,task.items.length,index,value);feedback='<div class="sp-sa-note bad">Die Zeitform ist noch nicht richtig.</div>';render(task);return}const r=S.right(themeNo(),task.id,task.items.length,index,item.sentence),x=r.s;clearStage(x,index);save(task,x,false);feedback=r.needsReview?'<div class="sp-sa-note hint">Richtig korrigiert. Der Satz kommt später noch einmal.</div>':'';render(task)}))
 }
 return true
}
function install(){if(!window.L8UI||window.L8UI.__spT3SentenceAnalysisV2)return false;const raw=window.L8UI.taskPage.bind(window.L8UI);window.L8UI.taskPage=function(){const id=new URLSearchParams(location.search).get('task'),task=(window.L8_THEME?.tasks||[]).find(t=>String(t?.id)===String(id));if(task?.spL8T3SentenceAnalysis)return render(task);return raw()};window.L8UI.__spT3SentenceAnalysisV2=true;return true}
const style=document.createElement('style');style.id='sp-l8t3-sentence-analysis-style-v2';style.textContent=`.sp-sa-head h1{margin:6px 0 8px}.sp-sa-kicker{font-weight:900;color:var(--muted);letter-spacing:.04em;text-transform:uppercase}.sp-sa-progress{display:flex;justify-content:space-between;gap:12px;margin-top:14px;font-weight:850}.sp-sa-bar{height:9px;border-radius:999px;background:#ececf2;overflow:hidden;margin-top:6px}.sp-sa-bar span{display:block;height:100%;background:var(--lesson-main,var(--l8-main,#68539b));border-radius:inherit}.sp-sa-card{margin-top:16px}.sp-sa-step{font-size:18px;font-weight:950;margin-bottom:14px}.sp-sa-built{min-height:76px;border:2px dashed var(--lesson-line,var(--l8-line,#d7d5df));border-radius:16px;padding:14px;display:flex;flex-wrap:wrap;gap:8px;align-items:center;background:#fafafd}.sp-sa-built.empty{color:#777}.sp-sa-built button,.sp-sa-pool button,.sp-sa-piece,.sp-sa-choices button{border:2px solid var(--lesson-line,var(--l8-line,#d7d5df));background:#fff;border-radius:12px;padding:10px 13px;font:inherit;font-weight:800;cursor:pointer}.sp-sa-pool{display:flex;flex-wrap:wrap;gap:9px;margin:18px 0}.sp-sa-actions{display:flex;gap:10px;justify-content:flex-end}.sp-sa-note{margin-top:14px;padding:10px 12px;border-radius:12px;font-weight:800}.sp-sa-note.bad{background:#fff0f0;color:#9d2828}.sp-sa-note.hint{background:#fff8dc;color:#725500}.sp-sa-note.ok{background:#eaf8ee;color:#287a42}.sp-sa-sentence-flow{display:flex;flex-wrap:wrap;gap:8px;align-items:center;padding:18px;border-radius:16px;background:var(--lesson-soft,var(--l8-soft,#f3effa));font-size:20px}.sp-sa-piece.role-sub{border-color:#3678b8;background:#eaf4ff}.sp-sa-piece.role-verb{border-color:#a15a22;background:#fff1e6}.sp-sa-role-questions{display:grid;gap:9px;margin:18px 0}.sp-sa-role-question{padding:12px 14px;border:2px solid var(--lesson-line,var(--l8-line,#d7d5df));border-radius:12px;background:#fff}.sp-sa-role-question.active{border-color:var(--lesson-main,var(--l8-main,#68539b));background:var(--lesson-soft,var(--l8-soft,#f3effa))}.sp-sa-role-question.done{background:#eaf8ee;border-color:#65a978}.sp-sa-choices{display:flex;flex-wrap:wrap;gap:9px}.sp-sa-feedback{min-height:16px}.sp-sa-finish{text-align:center}.sp-sa-finish>div:first-child{font-size:56px}@media(max-width:600px){.sp-sa-actions{flex-direction:column}.sp-sa-actions .l8-btn{width:100%}.sp-sa-built{min-height:64px}.sp-sa-built button,.sp-sa-pool button,.sp-sa-piece,.sp-sa-choices button{padding:9px 10px}}`;if(!document.getElementById(style.id))document.head.appendChild(style);
window.L8T3SentenceAnalysisUI={install,render};
})();
